export function normalizeName(value){
 return typeof value==='string'?value.replace(/[\u0000-\u001f\u007f]/g,'').replace(/\s+/g,' ').trim().slice(0,40).trim():'';
}

export function welcomeView({brand,themeButton,esc,bankSize,storageOK}){
 return `<div class="welcome-page"><header class="welcome-header">${brand()}${themeButton()}</header><main id="main" class="welcome-layout" tabindex="-1"><section class="welcome-intro"><h1>Sebelum mulai,<br>kenalan dulu.</h1><p>Satu langkah kecil untuk ruang belajar yang lebih personal. Isi nama panggilanmu, lalu mulai persiapan UKPPPG.</p><div class="welcome-facts"><span><strong>${bankSize}</strong>soal latihan</span><span><strong>8</strong>topik Pedagogi Umum</span></div></section><section class="card welcome-form"><h2>Kami panggil kamu siapa?</h2><p>Nama wajib diisi sebelum membuka materi dan tryout.</p><form id="onboarding-form"><label class="field" for="onboarding-name">Nama panggilan<input id="onboarding-name" data-name-input name="nickname" type="text" autocomplete="nickname" maxlength="40" required pattern=".*\\S.*" placeholder="Tulis namamu" aria-describedby="name-help profile-error" autofocus></label><p id="name-help" class="welcome-help">Maksimal 40 karakter. Nama disimpan di browser ini dan dapat diubah melalui profil.</p><p id="profile-error" class="name-error" role="status" aria-live="polite"></p><button type="submit" class="btn primary">Masuk ruang belajar</button></form><p class="welcome-privacy">${storageOK?'Tidak perlu email atau kata sandi. Riwayat belajarmu tersimpan di browser perangkat ini.':'Penyimpanan browser tidak tersedia. Nama berlaku selama halaman ini terbuka; saat berkunjung lagi kamu perlu mengisinya kembali.'}</p></section></main><footer class="welcome-footer">Latihan mandiri · Soal orisinal · PPG Calon Guru</footer></div>`;
}
